@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
  let i = gid.x + gid.y * nwg.x * 64u;
  let outer = P[0];
  let n = P[1];
  let inner = P[2];
  if (i >= outer * inner) { return; }
  let o = i / inner;
  let j = i % inner;
  let base = o * n * inner + j;
  var acc: f32 = A[base];
  for (var k = 1u; k < n; k = k + 1u) {
    let v = A[base + k * inner];
    acc = max(acc, v);
  }
  OUT[i] = acc;
}

kernels.matmul-naive:
@group(0) @binding(0) var<storage, read> A: array<f32>;
@group(0) @binding(1) var<storage, read> B: array<f32>;
@group(0) @binding(2) var<storage, read_write> OUT: array<f32>;
@group(0) @binding(3) var<storage, read> P: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let M = P[1];
  let K = P[2];
  let N = P[3];
  let col = gid.x;
  let row = gid.y;
  let b = gid.z;
  if (row >= M || col >= N) { return; }
  let aBase = b * M * K + row * K;
  let bBase = b * K * N + col;
  var acc: f32 = 0.0;
  for (var k = 0u; k < K; k = k + 1u) {
    acc = acc + A[aBase + k] * B[bBase + k * N];
  }
  OUT[b * M * N + row * N + col] = acc;
}

kernels.matmul-tiled:
@group(0) @binding(0) var<storage, read> A: array<f32>;
@group(0) @binding(1) var<storage, read> B: array<f32>;
@group(0) @binding(2) var<storage, read_write> OUT: array<f32>;
@group(0) @binding(3) var<storage, read> P: array<u32>;

var<workgroup> As: array<array<f32, 16>, 16>;
var<workgroup> Bs: array<array<f32, 16>, 16>;

@compute @workgroup_size(16, 16)
fn main(@builtin(workgroup_id) wg: vec3<u32>, @builtin(local_invocation_id) l: vec3<u32>) {
  let M = P[1];
  let K = P[2];
  let N = P[3];
  let b = wg.z;
  let row = wg.y * 16u + l.y;
  let col = wg.x * 16u + l.x;
  let aBase = b * M * K;
  let bBase = b * K * N;
  var acc: f32 = 0.0;
  let tiles = (K + 15u) / 16u;
  for (var t0 = 0u; t0 < tiles; t0 = t0 + 1u) {
    let ak = t0 * 16u + l.x;
    let bk = t0 * 16u + l.y;
    var av: f32 = 0.0;
    if (row < M && ak < K) { av = A[aBase + row * K + ak]; }
    var bv: f32 = 0.0;
    if (bk < K && col < N) { bv = B[bBase + bk * N + col]; }
    As[l.y][l.x] = av;
    Bs[l.y][l.x] = bv;
    workgroupBarrier();
    for (var k = 0u; k < 16u; k = k + 1u) {
      acc = acc + As[l.y][k] * Bs[k][l.x];
    }
    workgroupBarrier();
  }
  if (row < M && col < N) { OUT[b * M * N + row * N + col] = acc; }
}
